def backfill_months(apps, schema_editor):
    # 詳細なトークン・音声量の過去分は推測せず、既存の会話受付数だけ引き継ぐ。
    from django.conf import settings
    alias = schema_editor.connection.alias
    Daily = apps.get_model('blog', 'CocoChatUsage')
    Monthly = apps.get_model('blog', 'CocoMonthlyUsage')
    totals = {}
    for row in Daily.objects.using(alias).values('day', 'total_requests'):
        month = row['day'].replace(day=1)
        totals[month] = totals.get(month, 0) + row['total_requests']
    for month, total in totals.items():
        Monthly.objects.using(alias).update_or_create(month=month, defaults={'total_requests': total})
    apps.get_model('blog', 'CocoSettings').objects.using(alias).filter(pk=1).update(
        chat_daily_limit=max(0, settings.COCO_CHAT_GLOBAL_PER_DAY),
        chat_visitor_daily_limit=max(0, settings.COCO_CHAT_PER_VISITOR_DAY),
        chat_per_minute_limit=max(0, settings.COCO_CHAT_PER_MINUTE),
        chat_max_concurrent=max(0, settings.COCO_CHAT_MAX_CONCURRENT),
    )


